from decimal import Decimal, ROUND_HALF_UP, InvalidOperation


def calc_total(items: list[dict]) -> str:
    total = Decimal('0')

    for item in items:
        price = item.get('price')
        qty = item.get('qty')

        if not (isinstance(qty, int) and not isinstance(qty, bool) and qty >= 0):
            raise ValueError('Invalid quantity, must be a nonnegative integer.')

        try:
            price_decimal = Decimal(price)
            if not price_decimal.is_finite() or price_decimal < 0:
                raise ValueError()
        except (ValueError, TypeError, ArithmeticError, OverflowError, InvalidOperation):
            raise ValueError('Invalid price, must be a nonnegative finite decimal string.')

        total += price_decimal * qty

    return str(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

