import pytest
from app.cart_total import calc_total
from decimal import Decimal, InvalidOperation


def test_calc_total_empty_list():
    assert calc_total([]) == '0.00'

def test_calc_total_single_item():
    items = [{'price': '123.45', 'qty': 1}]
    assert calc_total(items) == '123.45'

def test_calc_total_multiple_items():
    items = [
        {'price': '123.45', 'qty': 1},
        {'price': '678.90', 'qty': 2}
    ]
    assert calc_total(items) == '1471.20'

def test_calc_total_invalid_price():
    with pytest.raises(ValueError, match='Invalid price, must be a nonnegative finite decimal string.'):
        calc_total([{'price': 'invalid', 'qty': 1}])

def test_calc_total_negative_price():
    with pytest.raises(ValueError, match='Invalid price, must be a nonnegative finite decimal string.'):
        calc_total([{'price': '-123.45', 'qty': 1}])

def test_calc_total_infinite_price():
    with pytest.raises(ValueError, match='Invalid price, must be a nonnegative finite decimal string.'):
        calc_total([{'price': 'Infinity', 'qty': 1}])

def test_calc_total_nan_price():
    with pytest.raises(ValueError, match='Invalid price, must be a nonnegative finite decimal string.'):
        calc_total([{'price': 'NaN', 'qty': 1}])

def test_calc_total_non_integer_qty():
    with pytest.raises(ValueError, match='Invalid quantity, must be a nonnegative integer.'):
        calc_total([{'price': '123.45', 'qty': 1.5}])

def test_calc_total_negative_qty():
    with pytest.raises(ValueError, match='Invalid quantity, must be a nonnegative integer.'):
        calc_total([{'price': '123.45', 'qty': -1}])

def test_calc_total_bool_qty():
    with pytest.raises(ValueError, match='Invalid quantity, must be a nonnegative integer.'):
        calc_total([{'price': '123.45', 'qty': True}])

def test_calc_total_does_not_mutate_inputs():
    items = [{'price': '123.45', 'qty': 1}]
    original_items = [{'price': '123.45', 'qty': 1}]
    calc_total(items)
    assert items == original_items
